                "cpp": "class Solution {\npublic:\n    int jump(vector<int>& nums) {\n        int jumps = 0, end = 0, far = 0;\n        for (int i = 0; i < (int)nums.size() - 1; i++) {\n            far = max(far, i + nums[i]);\n            if (i == end) {\n                jumps++;\n                end = far;\n            }\n        }\n        return jumps;\n    }\n};",
